    parameter [2:0] A = 3'b001, B = 3'b010, C = 3'b100;
    reg [2:0] current_state, next_state;
    always @(posedge clk) begin
        case(current_state)
            A: if (x && !y) begin next_state <= B; z <= 1'b0; end else if (!x && y) begin next_state <= C; z <= 1'b1; end else begin next_state <= A; z <= 1'b0; end
            B: if (x && !y) begin next_state <= A; z <= 1'b0; end else begin next_state <= B; z <= 1'b0; end
            C: if (!x && y) begin next_state <= A; z <= 1'b0; end else begin next_state <= C; z <= 1'b1; end
        endcase
        current_state <= next_state;
    end
